window.DATA={"stories":[{"id":"noe","name":"Noé","title":"Construir antes de ver","era":"Comienzos","place":"Antes del Diluvio","value":"Constancia","reference":"Génesis 6:9–22; 7:1–16","bible":"https://www.jw.org/es/biblioteca/biblia/biblia-estudio/libros/génesis/6/","source":"https://www.jw.org/es/biblioteca/libros/lecciones-historias-biblia/2/arca-de-noe/","summary":"En un mundo violento, Noé decidió escuchar a Jehová. Recibió instrucciones para construir un arca y las llevó a la práctica con su familia. El relato destaca una fe que se expresaba en trabajo constante, no solo en palabras. No se conoce con certeza el lugar donde construyeron el arca.","sequence":["Jehová da instrucciones a Noé.","Noé construye el arca.","La familia y los animales entran.","Llega el Diluvio."],"clues":["Mi tarea requirió constancia antes de ver el resultado.","Mi familia trabajó conmigo en una gran construcción.","Construí un arca siguiendo las instrucciones de Jehová."],"modern":{"context":"Hogar","situation":"En casa acordaron estudiar juntos, pero después de varios días les cuesta mantener la costumbre.","options":["Elegir una hora realista y repartir pequeñas tareas.","Intentar hacerlo todo de golpe un solo día.","Dejarlo hasta que a todos les sobre tiempo."],"correct":0,"explanation":"La constancia crece con pasos posibles y un propósito compartido. La aplicación es una propuesta del juego, no una instrucción dada a Noé.","action":"Acordar una pequeña rutina que puedan sostener esta semana.","talk":"¿Qué tarea sale mejor cuando colaboramos sin esperar resultados inmediatos?","responses":["Un horario realista permite que cada persona sepa cómo colaborar. No hace falta empezar con una rutina perfecta.","Concentrarlo todo en un solo día podría resultar agotador. La constancia necesita un ritmo que sí puedan mantener.","Esperar a que sobre tiempo puede dejar el acuerdo sin empezar. Una tarea pequeña ofrece un comienzo más concreto."],"line":"Piensa cómo expresarías tu respuesta con tus propias palabras."},"scene":"forest","bridge":{"past":"Llega el Diluvio.","value":"Constancia","today":"En casa acordaron estudiar juntos, pero después de varios días les cuesta mantener la costumbre.","action":"Acordar una pequeña rutina que puedan sostener esta semana."},"originalSourceArtwork":false},{"id":"abrahan","name":"Abrahán y Sara","title":"El valor del primer paso","era":"Patriarcas","place":"De Ur a Canaán","value":"Confianza","reference":"Génesis 12:1–9","bible":"https://www.jw.org/es/biblioteca/biblia/biblia-estudio/libros/génesis/12/","source":"https://www.jw.org/es/biblioteca/libros/lecciones-historias-biblia/3/abrahan-sara/","summary":"Abrahán y Sara dejaron una vida conocida para seguir la dirección de Jehová. Su recorrido pasó por Harán y continuó hacia Canaán. No tuvieron todas las respuestas por adelantado, pero su confianza influyó en sus decisiones. El relato no convierte cualquier mudanza o incertidumbre en un mandato divino.","sequence":["Viven en Ur.","Salen y llegan a Harán.","Abrahán continúa hacia Canaán.","Recorre la tierra y vive en tiendas."],"clues":["Dejé una ciudad y aprendí a vivir en tiendas.","Sara me acompañó en un largo viaje.","Salí de Ur y recibí una promesa sobre mi descendencia."],"modern":{"context":"Cambios","situation":"Tu familia se muda y te preocupa no conocer a nadie en el nuevo lugar.","options":["Hablar de lo que preocupa y preparar juntos el primer paso.","Fingir que nadie siente miedo.","Pensar que todos los cambios siempre saldrán mal."],"correct":0,"explanation":"Expresar lo que sentimos y buscar apoyo permite afrontar cambios con más serenidad. Confiar no equivale a ignorar los preparativos prácticos.","action":"Escribir una preocupación y una acción concreta para afrontarla.","talk":"¿Cómo podemos acompañar a quien está empezando una etapa nueva?","responses":["Hablar del miedo permite preparar juntos la nueva etapa sin fingir seguridad.","Ocultar el miedo puede impedir que recibas apoyo. Reconocer una preocupación no te hace menos valiente.","Anticipar solo resultados negativos puede aumentar la incertidumbre. Puedes reconocer riesgos y preparar un primer paso."],"line":"Piensa cómo expresarías tu respuesta con tus propias palabras."},"scene":"desert","bridge":{"past":"Recorre la tierra y vive en tiendas.","value":"Confianza","today":"Tu familia se muda y te preocupa no conocer a nadie en el nuevo lugar.","action":"Escribir una preocupación y una acción concreta para afrontarla."},"originalSourceArtwork":false},{"id":"jose","name":"José","title":"Reservas para el mañana","era":"Patriarcas","place":"Egipto","value":"Previsión y perdón","reference":"Génesis 41:25–57; 45:1–15","bible":"https://www.jw.org/es/biblioteca/biblia/biblia-estudio/libros/génesis/41/","source":"https://www.jw.org/es/biblioteca/libros/lecciones-historias-biblia/4/suenos-faraon/","summary":"José explicó al faraón que habría años de abundancia seguidos de hambre. Organizó reservas de alimento que después ayudaron a muchas personas. Cuando sus hermanos llegaron a Egipto, no se dejó dominar por la venganza. Su historia permite reflexionar tanto sobre la previsión como sobre el perdón.","sequence":["El faraón tiene sueños.","José explica su significado.","Se almacena alimento en años de abundancia.","Se distribuye alimento durante la escasez."],"clues":["Pasé de estar preso a administrar alimentos.","Mis hermanos llegaron a pedirme ayuda sin reconocerme.","Organicé reservas de grano en Egipto."],"modern":{"context":"Familia","situation":"Tu hermano reconoce que estropeó algo tuyo y propone repararlo. Todavía te sientes molesto.","options":["Escuchar su disculpa y acordar cómo reparar el daño.","Recordárselo en cada conversación.","Romper algo suyo para equilibrar las cosas."],"correct":0,"explanation":"El perdón no niega el daño ni elimina la necesidad de repararlo. El ejemplo de José invita a no convertir el resentimiento en venganza.","action":"Practicar una frase para hablar de un desacuerdo sin atacar a la persona.","talk":"¿Qué diferencia hay entre perdonar, recuperar la confianza y reparar un daño?","responses":["Escuchar y acordar una reparación permite atender el daño sin usarlo como un arma. La confianza puede recuperarse poco a poco.","Recordar el error en cada conversación podría mantener abierto el conflicto sin resolver la reparación.","Dañar algo suyo sumaría otro problema. Puedes expresar tu enfado y poner límites sin vengarte."],"line":"Piensa cómo expresarías tu respuesta con tus propias palabras."},"scene":"egypt","bridge":{"past":"Se distribuye alimento durante la escasez.","value":"Previsión y perdón","today":"Tu hermano reconoce que estropeó algo tuyo y propone repararlo. Todavía te sientes molesto.","action":"Practicar una frase para hablar de un desacuerdo sin atacar a la persona."},"originalSourceArtwork":false},{"id":"moises","name":"Moisés","title":"Un paso entre las aguas","era":"Éxodo","place":"Mar Rojo","value":"Confianza y calma","reference":"Éxodo 14:10–31","bible":"https://www.jw.org/es/biblioteca/biblia/biblia-estudio/libros/éxodo/14/","source":"https://www.jw.org/es/biblioteca/libros/lecciones-historias-biblia/4/mar-rojo-se-divide/","summary":"Los israelitas se encontraron entre el mar y el ejército egipcio. Moisés los animó a confiar en Jehová. Según el relato, Jehová abrió un camino por el mar y el pueblo cruzó sobre terreno seco. La Biblia atribuye la liberación a Dios; ningún reto del juego reproduce ese milagro.","sequence":["El pueblo sale de Egipto.","Los egipcios lo persiguen.","Jehová abre un camino por el mar.","Los israelitas cruzan."],"clues":["Guié a un pueblo que había vivido en esclavitud.","Animé a los israelitas cuando parecían no tener salida.","Extendí mi mano sobre el mar siguiendo la dirección de Jehová."],"modern":{"context":"Preocupación","situation":"Tienes varias tareas pendientes y pensar en todas a la vez te bloquea.","options":["Hacer una pausa, orar y ordenar el siguiente paso.","Decidir que nada tiene solución.","Responder mal a quien intenta ayudarte."],"correct":0,"explanation":"Podemos buscar calma, apoyo y dirección antes de actuar. El relato no promete que hoy todos los problemas se resuelvan milagrosamente.","action":"Dividir una tarea grande en tres acciones pequeñas.","talk":"¿Qué palabras ayudan cuando alguien se siente atrapado por sus preocupaciones?","responses":["Una pausa y un siguiente paso manejable pueden ayudarte a salir del bloqueo. Pedir apoyo también es válido.","Pensar que nada tiene solución podría impedirte identificar una parte que sí puedes resolver.","Responder mal puede alejar a quien intenta acompañarte. Puedes pedir unos minutos antes de hablar."],"line":"Piensa cómo expresarías tu respuesta con tus propias palabras."},"scene":"coast","bridge":{"past":"Los israelitas cruzan.","value":"Confianza y calma","today":"Tienes varias tareas pendientes y pensar en todas a la vez te bloquea.","action":"Dividir una tarea grande en tres acciones pequeñas."},"originalSourceArtwork":false},{"id":"rahab","name":"Rahab","title":"Una decisión con valor","era":"Conquista y jueces","place":"Jericó","value":"Valor","reference":"Josué 2:1–21; 6:22–25","bible":"https://www.jw.org/es/biblioteca/biblia/biblia-estudio/libros/josué/2/","source":"https://www.jw.org/es/biblioteca/libros/lecciones-historias-biblia/6/rahab-esconde-espias/","summary":"Rahab reconoció el poder de Jehová y ayudó a los mensajeros israelitas. Siguió las instrucciones relacionadas con una cuerda de color rojo y reunió a su familia en su casa. Su historia destaca una confianza que se convirtió en acciones. La aplicación actual se centra en el valor, no en imitar operaciones de espionaje.","sequence":["Llegan dos mensajeros a Jericó.","Rahab les presta ayuda.","Recibe y sigue las instrucciones sobre la cuerda.","Rahab y su familia son rescatados."],"clues":["Vivía en una ciudad amurallada.","Ayudé a dos mensajeros y pensé en mi familia.","Una cuerda roja identificó mi casa en Jericó."],"modern":{"context":"Escuela","situation":"Alguien queda excluido de una actividad y te preocupa que se burlen de ti si lo incluyes.","options":["Invitarlo con respeto y pedir apoyo a un adulto si hay acoso.","Unirte a la burla para pasar inadvertido.","Decir que ayudarás, pero no hacer nada."],"correct":0,"explanation":"El valor puede mostrarse con una acción tranquila y segura. No hace falta exponerse al peligro para tratar bien a otra persona.","action":"Pensar en una manera segura de incluir a alguien.","talk":"¿Cuándo una pequeña acción requiere mucho valor?","responses":["Invitar con respeto favorece la inclusión. Ante acoso, buscar apoyo es parte del valor, no una falta de él.","Sumarte a la burla puede agravar el daño a esa persona aunque momentáneamente te proteja de las críticas.","Una promesa sin acción no cambia la exclusión. Busca un gesto seguro y posible."],"line":"Piensa cómo expresarías tu respuesta con tus propias palabras."},"scene":"city","bridge":{"past":"Rahab y su familia son rescatados.","value":"Valor","today":"Alguien queda excluido de una actividad y te preocupa que se burlen de ti si lo incluyes.","action":"Pensar en una manera segura de incluir a alguien."},"originalSourceArtwork":false},{"id":"rut","name":"Rut y Noemí","title":"Nadie camina sola","era":"Conquista y jueces","place":"Moab y Belén","value":"Lealtad","reference":"Rut 1:16–22; 2:1–17","bible":"https://www.jw.org/es/biblioteca/biblia/biblia-estudio/libros/rut/2/","source":"https://www.jw.org/es/biblioteca/libros/lecciones-historias-biblia/6/rut-noemi/","summary":"Rut acompañó a Noemí cuando regresó a Belén. Para conseguir alimento recogió espigas en el campo de Boaz, quien la trató con consideración. Su cariño no quedó en una promesa: se expresó en compañía y trabajo cotidiano. Noemí también compartió orientación y experiencia con Rut.","sequence":["Noemí decide regresar a Belén.","Rut elige acompañarla.","Llegan al comienzo de la cosecha.","Rut recoge espigas en el campo de Boaz."],"clues":["Dejé Moab para acompañar a alguien que quería.","Recogí espigas para ayudar a mi familia.","No abandoné a Noemí."],"modern":{"context":"Familia","situation":"Un familiar mayor está solo y últimamente casi nadie lo visita.","options":["Preguntar qué necesita y acordar una visita o llamada.","Suponer que prefiere estar siempre solo.","Prometer algo que sabemos que no cumpliremos."],"correct":0,"explanation":"La lealtad se reconoce en el cuidado constante. Escuchar qué ayuda necesita la persona evita decidir todo por ella.","action":"Organizar un gesto de compañía que realmente puedan cumplir.","talk":"¿Cómo demostramos cariño cuando ya pasó el primer momento de preocupación?","responses":["Preguntar permite ofrecer la compañía que esa persona desea y cumplir un compromiso realista.","Suponer que prefiere la soledad podría dejar sin escuchar una necesidad. Conviene preguntarle.","Una promesa que no puedes cumplir puede producir desilusión. Ofrece menos, pero hazlo de verdad."],"line":"Piensa cómo expresarías tu respuesta con tus propias palabras."},"scene":"field","bridge":{"past":"Rut recoge espigas en el campo de Boaz.","value":"Lealtad","today":"Un familiar mayor está solo y últimamente casi nadie lo visita.","action":"Organizar un gesto de compañía que realmente puedan cumplir."},"originalSourceArtwork":false},{"id":"samuel","name":"Samuel","title":"Aprender a escuchar","era":"Conquista y jueces","place":"Siló","value":"Atención","reference":"1 Samuel 3:1–10","bible":"https://www.jw.org/es/biblioteca/biblia/biblia-estudio/libros/1-samuel/3/","source":"https://www.jw.org/es/biblioteca/libros/lecciones-historias-biblia/6/dios-llama-samuel/","summary":"Samuel servía en el tabernáculo junto a Elí. Una noche oyó que lo llamaban y, al principio, pensó que era Elí. Con su ayuda entendió quién lo estaba llamando y se dispuso a escuchar. El relato presenta un episodio particular; no enseña a interpretar cualquier voz o pensamiento como un mensaje divino.","sequence":["Samuel oye que lo llaman.","Va a ver a Elí.","Elí comprende lo que sucede y lo orienta.","Samuel se dispone a escuchar a Jehová."],"clues":["De joven servía junto a un hombre llamado Elí.","Una noche pensé varias veces que él me llamaba.","Aprendí a escuchar un mensaje de Jehová en Siló."],"modern":{"context":"Hogar","situation":"Mientras alguien te explica algo importante, sigues mirando el teléfono.","options":["Guardar el teléfono y confirmar que entendiste.","Responder sin haber escuchado.","Interrumpir para terminar más rápido."],"correct":0,"explanation":"Escuchar con atención es una forma de respeto. Preguntar cuando no entendemos evita suposiciones.","action":"Dejar las pantallas a un lado durante una conversación.","talk":"¿Cómo notas que otra persona te está escuchando de verdad?","responses":["Guardar el teléfono y confirmar lo entendido hace visible tu atención.","Responder sin escuchar puede generar errores y hacer que la otra persona no se sienta atendida.","Interrumpir para terminar antes puede impedir comprender lo importante. Pide una aclaración con calma."],"line":"Piensa cómo expresarías tu respuesta con tus propias palabras."},"scene":"courtyard","bridge":{"past":"Samuel se dispone a escuchar a Jehová.","value":"Atención","today":"Mientras alguien te explica algo importante, sigues mirando el teléfono.","action":"Dejar las pantallas a un lado durante una conversación."},"originalSourceArtwork":false},{"id":"jonatan","name":"David y Jonatán","title":"La amistad no compite","era":"Reyes y profetas","place":"Israel","value":"Amistad","reference":"1 Samuel 18:1–4; 23:16–18","bible":"https://www.jw.org/es/biblioteca/biblia/biblia-estudio/libros/1-samuel/18/","source":"https://www.jw.org/es/biblioteca/libros/lecciones-historias-biblia/7/jonatan-david/","summary":"Jonatán era hijo del rey Saúl, pero no trató a David como un rival al que debía desplazar. Su amistad se manifestó en lealtad y apoyo. En una etapa difícil, Jonatán animó a David a seguir confiando en Jehová. Su ejemplo invita a alegrarnos por el bien de nuestros amigos.","sequence":["David y Jonatán se hacen amigos.","Jonatán demuestra su lealtad.","David atraviesa una etapa de persecución.","Jonatán lo anima a confiar en Jehová."],"clues":["Mi padre era rey, pero mi amistad no se basó en competir.","Apoyé a un amigo que atravesaba dificultades.","Fui un amigo leal de David y era hijo de Saúl."],"modern":{"context":"Amistades","situation":"Un amigo consigue una oportunidad que tú también deseabas.","options":["Felicitarlo sinceramente y seguir trabajando en tus propias metas.","Restarle importancia a su esfuerzo.","Alejarte sin explicarle qué te pasa."],"correct":0,"explanation":"La alegría por el bien de otro fortalece la amistad. Reconocer nuestros sentimientos también ayuda a no actuar por celos.","action":"Enviar un mensaje sincero de reconocimiento a un amigo.","talk":"¿Qué diferencia hay entre admirar a alguien y compararse constantemente con él?","responses":["Puedes felicitar a tu amigo y reconocer al mismo tiempo tu propia decepción. Ambas cosas pueden coexistir.","Restar importancia a su esfuerzo puede herir la amistad sin aliviar lo que sientes.","Alejarte sin explicarte puede generar confusión. Puedes tomarte tiempo y luego hablar con sinceridad."],"line":"Piensa cómo expresarías tu respuesta con tus propias palabras."},"scene":"forest","bridge":{"past":"Jonatán lo anima a confiar en Jehová.","value":"Amistad","today":"Un amigo consigue una oportunidad que tú también deseabas.","action":"Enviar un mensaje sincero de reconocimiento a un amigo."},"originalSourceArtwork":false},{"id":"abigail","name":"Abigaíl","title":"Palabras que cambian el rumbo","era":"Reyes y profetas","place":"Región de Carmelo","value":"Autocontrol","reference":"1 Samuel 25:14–35","bible":"https://www.jw.org/es/biblioteca/biblia/biblia-estudio/libros/1-samuel/25/","source":"https://www.jw.org/es/biblioteca/libros/seamos-valientes-andar-dios/dias-reyes-reconstruccion-jerusalen/abigail-mujer-apago-furia-hombres/","summary":"Después de los insultos de Nabal, David reaccionó con furia. Abigaíl actuó con sensatez y le recordó las consecuencias de responder con violencia. David aceptó sus palabras y cambió de rumbo. La enseñanza no exige que una víctima confronte a una persona violenta: ante un peligro real, la prioridad es ponerse a salvo.","sequence":["Nabal rechaza e insulta a los mensajeros.","David se enfurece.","Abigaíl interviene con sensatez.","David escucha y desiste de vengarse."],"clues":["Mi intervención ayudó a evitar una tragedia.","No respondí a la furia con más furia.","David aceptó mi consejo después de los insultos de Nabal."],"modern":{"context":"Conversaciones","situation":"Recibes un mensaje que parece ofensivo y ya estás escribiendo una respuesta dura.","options":["Esperar, aclarar lo que quiso decir y responder con calma.","Reenviarlo para que todos se enfaden.","Contestar con un insulto más fuerte."],"correct":0,"explanation":"Una pausa permite considerar otras explicaciones y las consecuencias de nuestras palabras. En caso de amenazas, busca ayuda y no te expongas.","action":"Practicar: “Quiero entender lo que dijiste antes de responder”.","talk":"¿Qué nos ayuda a aceptar un consejo cuando estamos molestos?","responses":["Una pausa y una pregunta pueden aclarar un malentendido antes de responder. Si hay amenazas, la prioridad es protegerte.","Reenviar el mensaje para enfadar a otros puede ampliar el conflicto y afectar la privacidad.","Un insulto más fuerte puede escalar la discusión. Estar molesto no obliga a responder inmediatamente."],"line":"Piensa cómo expresarías tu respuesta con tus propias palabras."},"scene":"desert","bridge":{"past":"David escucha y desiste de vengarse.","value":"Autocontrol","today":"Recibes un mensaje que parece ofensivo y ya estás escribiendo una respuesta dura.","action":"Practicar: “Quiero entender lo que dijiste antes de responder”."},"originalSourceArtwork":false},{"id":"salomon","name":"Salomón","title":"La mejor pregunta","era":"Reyes y profetas","place":"Jerusalén","value":"Sabiduría","reference":"1 Reyes 3:5–12","bible":"https://www.jw.org/es/biblioteca/biblia/biblia-estudio/libros/1-reyes/3/","source":"https://www.jw.org/es/biblioteca/libros/lecciones-historias-biblia/8/rey-salomon-templo/","summary":"Al comenzar su reinado, Salomón reconoció que necesitaba ayuda para dirigir al pueblo. En lugar de pedir riqueza, solicitó capacidad para juzgar con sabiduría. El relato resalta el valor de reconocer nuestras limitaciones y buscar discernimiento antes de asumir una responsabilidad.","sequence":["Salomón asume el reinado.","Jehová le invita a expresar una petición.","Salomón pide sabiduría para juzgar.","Jehová responde a su petición."],"clues":["Fui rey después de David.","Mi petición no se centró en riquezas.","Pedí un corazón que escuchara para juzgar al pueblo."],"modern":{"context":"Decisiones","situation":"Te proponen coordinar una actividad que nunca has organizado.","options":["Reconocer lo que necesitas aprender y pedir orientación.","Prometer que puedes hacerlo todo sin ayuda.","Ocultar tus dudas hasta el último día."],"correct":0,"explanation":"Pedir ayuda no resta valor a una responsabilidad; puede mejorar la manera de cumplirla.","action":"Anotar dos preguntas antes de tomar una decisión importante.","talk":"¿A quién podemos consultar cuando nos falta experiencia?","responses":["Pedir orientación te permite preparar una responsabilidad nueva con expectativas realistas.","Prometer hacerlo todo sin ayuda puede ocultar necesidades importantes hasta que aparezcan dificultades.","Guardar las dudas hasta el último día reduce el tiempo para recibir apoyo. Preguntar a tiempo facilita el trabajo."],"line":"Piensa cómo expresarías tu respuesta con tus propias palabras."},"scene":"palace","bridge":{"past":"Jehová responde a su petición.","value":"Sabiduría","today":"Te proponen coordinar una actividad que nunca has organizado.","action":"Anotar dos preguntas antes de tomar una decisión importante."},"originalSourceArtwork":false},{"id":"viuda","name":"La viuda de Sarepta","title":"Lo pequeño también ayuda","era":"Reyes y profetas","place":"Sarepta","value":"Generosidad","reference":"1 Reyes 17:8–16","bible":"https://www.jw.org/es/biblioteca/biblia/biblia-estudio/libros/1-reyes/17/","source":"https://www.jw.org/es/biblioteca/libros/lecciones-historias-biblia/8/viuda-sarepta-elias/","summary":"En un tiempo de escasez, una viuda de Sarepta recibió a Elías. Aunque tenía muy poco alimento, actuó de acuerdo con el mensaje que él le transmitió. El relato cuenta que Jehová mantuvo su provisión de harina y aceite. No es una promesa de que dar dinero o bienes hoy produzca una recompensa material.","sequence":["Hay escasez de alimento.","Elías llega a Sarepta.","La viuda prepara alimento con lo poco que tiene.","La harina y el aceite no se agotan durante la escasez."],"clues":["Vivía fuera de Israel y atravesaba una época de escasez.","Compartí alimento con un profeta.","Mi harina y mi aceite no se agotaron mientras hospedaba a Elías."],"modern":{"context":"Comunidad","situation":"Te gustaría ayudar a un vecino, pero no tienes dinero para un regalo.","options":["Preguntar si puedes ayudar con una tarea o dedicarle tiempo.","Pensar que sin dinero no se puede ayudar.","Prometer un regalo que no puedes costear."],"correct":0,"explanation":"La generosidad también puede expresarse con tiempo, atención y habilidades. Debe respetar las necesidades y posibilidades de todos.","action":"Ofrecer una ayuda pequeña y concreta sin esperar nada a cambio.","talk":"¿Qué ayuda sin costo has recibido y todavía recuerdas?","responses":["Una tarea o un rato de atención puede ser útil sin exigir un gasto que no puedes asumir.","El dinero no es la única forma de ayudar. Tu tiempo o una habilidad también pueden servir.","Prometer algo que no puedes costear puede ponerte en dificultad. Tu ayuda debe respetar tus posibilidades."],"line":"Piensa cómo expresarías tu respuesta con tus propias palabras."},"scene":"village","bridge":{"past":"La harina y el aceite no se agotan durante la escasez.","value":"Generosidad","today":"Te gustaría ayudar a un vecino, pero no tienes dinero para un regalo.","action":"Ofrecer una ayuda pequeña y concreta sin esperar nada a cambio."},"originalSourceArtwork":false},{"id":"naaman","name":"Naamán","title":"Escuchar cambia las cosas","era":"Reyes y profetas","place":"Siria y el Jordán","value":"Humildad","reference":"2 Reyes 5:1–15","bible":"https://www.jw.org/es/biblioteca/biblia/biblia-estudio/libros/2-reyes/5/","source":"https://www.jw.org/es/biblioteca/libros/lecciones-historias-biblia/9/naaman-leproso/","summary":"Una niña israelita habló del profeta Eliseo. Naamán acudió a él, pero se molestó porque las instrucciones no eran lo que esperaba. Sus servidores lo animaron a reconsiderarlas. Finalmente se sumergió siete veces en el Jordán y, según el relato, fue curado. Este episodio no sustituye la atención médica actual.","sequence":["La niña habla de Eliseo.","Naamán recibe instrucciones.","Sus servidores lo animan a escuchar.","Se baña siete veces en el Jordán y se cura."],"clues":["Me costó aceptar unas instrucciones sencillas.","Escuché el consejo de mis servidores.","Me sumergí siete veces en el Jordán siguiendo el mensaje de Eliseo."],"modern":{"context":"Trabajo","situation":"Una persona con menos experiencia te señala un error que cometiste.","options":["Revisar lo que dice y agradecer la observación.","Descartarlo solo por su edad o experiencia.","Cambiar de tema para que nadie lo note."],"correct":0,"explanation":"Una sugerencia puede ser útil aunque venga de alguien inesperado. Revisar la información vale más que defender el orgullo.","action":"Practicar una respuesta agradecida ante una corrección.","talk":"¿Qué nos cuesta más: equivocarnos o reconocerlo?","responses":["Revisar la observación permite aprender por su contenido, no por la edad de quien habla.","Descartar una corrección por la experiencia de quien la ofrece podría hacerte perder información útil.","Cambiar de tema puede ocultar el error sin resolverlo. Reconocerlo deja espacio para corregirlo."],"line":"Piensa cómo expresarías tu respuesta con tus propias palabras."},"scene":"river","bridge":{"past":"Se baña siete veces en el Jordán y se cura.","value":"Humildad","today":"Una persona con menos experiencia te señala un error que cometiste.","action":"Practicar una respuesta agradecida ante una corrección."},"originalSourceArtwork":false},{"id":"jonas","name":"Jonás","title":"Aprender a mirar de nuevo","era":"Reyes y profetas","place":"Nínive","value":"Compasión","reference":"Jonás 3:1–10; 4:1–11","bible":"https://www.jw.org/es/biblioteca/biblia/biblia-estudio/libros/jonás/4/","source":"https://www.jw.org/es/biblioteca/libros/lecciones-historias-biblia/9/jonas/","summary":"Jonás huyó de la misión que recibió, pero después fue a Nínive. Sus habitantes cambiaron de conducta y Jehová les mostró misericordia. Jonás necesitó aprender que las personas importaban más que su deseo de ver un castigo. El relato invita a revisar nuestros prejuicios y a reconocer la posibilidad de cambiar.","sequence":["Jonás recibe la misión y huye.","Jehová lo rescata y vuelve a enviarlo.","Jonás predica en Nínive.","Jehová le enseña a mostrar compasión."],"clues":["Intenté alejarme de una misión.","Jehová me dio otra oportunidad.","Aprendí una lección sobre los habitantes de Nínive y una planta."],"modern":{"context":"Amistades","situation":"Un compañero que solía portarse mal está intentando mejorar.","options":["Observar sus cambios y tratarlo con respeto, manteniendo límites prudentes.","Decidir que nunca podrá cambiar.","Recordarle cada día todos sus errores."],"correct":0,"explanation":"Dar una oportunidad no obliga a ignorar conductas dañinas. Permite reconocer mejoras reales sin aferrarnos a una etiqueta.","action":"Pensar en una ocasión en que alguien te permitió empezar de nuevo.","talk":"¿Cómo distinguir entre ser compasivos y pasar por alto un peligro?","responses":["Reconocer mejoras no exige olvidar lo ocurrido ni confiar de inmediato. El respeto puede convivir con límites prudentes.","Decidir que alguien nunca cambiará puede impedirte reconocer mejoras reales. Puedes observar sin bajar tus límites.","Recordarle todos los errores cada día puede dificultar una convivencia respetuosa sin aumentar tu seguridad."],"line":"Piensa cómo expresarías tu respuesta con tus propias palabras."},"scene":"city","bridge":{"past":"Jehová le enseña a mostrar compasión.","value":"Compasión","today":"Un compañero que solía portarse mal está intentando mejorar.","action":"Pensar en una ocasión en que alguien te permitió empezar de nuevo."},"cinematicImage":"https://cms-imgp.jw-cdn.org/img/p/jcm/univ/pt/jcm_univ_lg.jpg","modernImage":"https://cms-imgp.jw-cdn.org/img/p/2026323/univ/art/2026323_univ_sqr_xl.jpg","originalSourceArtwork":false},{"id":"josias","name":"Josías","title":"Cuando aprender te mueve","era":"Reyes y profetas","place":"Jerusalén","value":"Aprendizaje","reference":"2 Reyes 22:8–13; 23:1–3","bible":"https://www.jw.org/es/biblioteca/biblia/biblia-estudio/libros/2-reyes/22/","source":"https://www.jw.org/es/biblioteca/libros/lecciones-historias-biblia/9/dios-rey-josias/","summary":"Durante las reparaciones del templo se encontró el libro de la Ley. Cuando Josías escuchó su contenido, comprendió que el pueblo necesitaba cambiar. No se limitó a admirar el hallazgo: buscó orientación e impulsó medidas relacionadas con lo que había aprendido.","sequence":["Se repara el templo.","Se encuentra el libro de la Ley.","Josías escucha su contenido.","Se toman medidas para volver a obedecer a Jehová."],"clues":["Fui rey desde muy joven.","Un hallazgo en el templo me impulsó a actuar.","Escuché el libro de la Ley y promoví cambios en Judá."],"modern":{"context":"Hábitos","situation":"Descubres que una costumbre tuya perjudica el tiempo que compartes con la familia.","options":["Elegir un cambio concreto y revisar cómo va funcionando.","Leer más sobre el tema sin intentar ningún cambio.","Culpar a los demás de toda la situación."],"correct":0,"explanation":"Aprender tiene más efecto cuando lo transformamos en acciones realistas. No necesitamos cambiar todo de una vez.","action":"Cambiar una costumbre pequeña durante esta semana.","talk":"¿Qué aprendimos recientemente que ya podríamos poner en práctica?","responses":["Un cambio pequeño y revisable convierte lo aprendido en una experiencia concreta.","Informarte puede ser útil, pero sin una acción la costumbre seguirá igual. Escoge un primer paso manejable.","Culpar a todos los demás puede impedir reconocer qué parte sí está bajo tu control."],"line":"Piensa cómo expresarías tu respuesta con tus propias palabras."},"scene":"courtyard","bridge":{"past":"Se toman medidas para volver a obedecer a Jehová.","value":"Aprendizaje","today":"Descubres que una costumbre tuya perjudica el tiempo que compartes con la familia.","action":"Cambiar una costumbre pequeña durante esta semana."},"originalSourceArtwork":false},{"id":"daniel","name":"Daniel","title":"Convicciones con serenidad","era":"Exilio y regreso","place":"Babilonia","value":"Integridad","reference":"Daniel 6:4–23","bible":"https://www.jw.org/es/biblioteca/biblia/biblia-estudio/libros/daniel/6/","source":"https://www.jw.org/es/biblioteca/libros/lecciones-historias-biblia/10/daniel-hoyo-leones/","summary":"Los adversarios de Daniel usaron una prohibición contra él. Daniel mantuvo su costumbre de orar a Jehová y terminó en el hoyo de los leones. El relato cuenta que Dios lo protegió. Su ejemplo destaca la integridad, pero no promete inmunidad frente a las consecuencias de nuestras decisiones.","sequence":["Los adversarios promueven una prohibición.","Daniel continúa orando a Jehová.","Lo arrojan al hoyo de los leones.","El rey descubre que Daniel está vivo."],"clues":["Mis adversarios no encontraban corrupción en mi trabajo.","Mantuve mi costumbre de orar pese a una prohibición.","Jehová me protegió en el hoyo de los leones."],"modern":{"context":"Escuela","situation":"Un grupo insiste en que copies una respuesta para no quedarte atrás.","options":["Explicar con respeto que prefieres hacer tu propio trabajo.","Copiar y decir que todos lo hacen.","Burlarte de quienes deciden algo distinto."],"correct":0,"explanation":"La integridad puede expresarse sin agresividad ni superioridad. Podemos ser firmes y respetuosos al mismo tiempo.","action":"Preparar una frase breve para rechazar una presión sin discutir.","talk":"¿Qué ayuda a mantener una convicción cuando estamos solos?","responses":["Una negativa breve y respetuosa permite mantener tu decisión sin atacar a nadie.","Que otros copien no elimina tu responsabilidad. Puedes pedir ayuda con lo que no entiendes.","Burlarte puede convertir una decisión firme en un conflicto. No necesitas humillar para mantener tus valores."],"line":"Piensa cómo expresarías tu respuesta con tus propias palabras."},"scene":"palace","bridge":{"past":"El rey descubre que Daniel está vivo.","value":"Integridad","today":"Un grupo insiste en que copies una respuesta para no quedarte atrás.","action":"Preparar una frase breve para rechazar una presión sin discutir."},"originalSourceArtwork":false},{"id":"ester","name":"Ester","title":"Valor con un buen momento","era":"Exilio y regreso","place":"Susa","value":"Valor y prudencia","reference":"Ester 4:10–17; 5:1–8; 7:1–6","bible":"https://www.jw.org/es/biblioteca/biblia/biblia-estudio/libros/ester/4/","source":"https://www.jw.org/es/biblioteca/libros/lecciones-historias-biblia/10/reina-ester-salva-pueblo/","summary":"Ester supo que su pueblo estaba amenazado. Buscó el apoyo de Mardoqueo y actuó con valor, aun sabiendo que acercarse al rey implicaba riesgos. Escogió cuidadosamente cómo y cuándo hablar. Su historia permite conversar sobre la valentía acompañada de preparación y apoyo.","sequence":["Ester conoce la amenaza contra su pueblo.","Pide apoyo a Mardoqueo y a los judíos.","Se presenta ante el rey y organiza los banquetes.","Expone la amenaza de Hamán."],"clues":["Vivía en el palacio de Susa.","Mardoqueo me animó a actuar por mi pueblo.","Fui una reina que habló con valor ante una amenaza."],"modern":{"context":"Conversaciones","situation":"Necesitas hablar de un problema importante con alguien de tu familia.","options":["Elegir un momento tranquilo y explicar el problema con respeto.","Esperar hasta explotar de enojo.","Acusar a la persona delante de todo el mundo."],"correct":0,"explanation":"El momento y la forma de hablar pueden facilitar que nos escuchen. Cuando existe peligro o maltrato, se necesita apoyo y protección, no solo una conversación.","action":"Preparar qué quieres comunicar y qué ayuda necesitas.","talk":"¿Cuándo es mejor pedir apoyo antes de abordar una conversación difícil?","responses":["Elegir el momento y explicar qué ayuda necesitas puede facilitar la conversación.","Esperar a explotar puede hacer más difícil expresar lo importante. Busca apoyo y prepara tus palabras.","Una acusación pública puede generar vergüenza y resistencia. En problemas serios, elige apoyo y protección adecuados."],"line":"Piensa cómo expresarías tu respuesta con tus propias palabras."},"scene":"palace","bridge":{"past":"Expone la amenaza de Hamán.","value":"Valor y prudencia","today":"Necesitas hablar de un problema importante con alguien de tu familia.","action":"Preparar qué quieres comunicar y qué ayuda necesitas."},"originalSourceArtwork":false},{"id":"nehemias","name":"Nehemías","title":"Juntos, piedra a piedra","era":"Exilio y regreso","place":"Jerusalén","value":"Cooperación","reference":"Nehemías 2:11–18; 3:1–32; 6:15","bible":"https://www.jw.org/es/biblioteca/biblia/biblia-estudio/libros/nehemías/2/","source":"https://www.jw.org/es/biblioteca/libros/lecciones-historias-biblia/10/murallas-jerusalen-nehemias/","summary":"Nehemías conoció la situación de Jerusalén, oró y se preparó para ayudar. Al llegar examinó las murallas y animó al pueblo. Distintos grupos trabajaron en diferentes tramos. La reconstrucción muestra cómo una meta compartida necesita planificación, ánimo y colaboración.","sequence":["Nehemías conoce el problema y busca ayuda.","Llega a Jerusalén y examina las murallas.","El pueblo organiza y realiza el trabajo.","Se termina la reconstrucción."],"clues":["Me preocupé por una ciudad con sus murallas dañadas.","Antes de empezar, examiné lo que había que hacer.","Organicé la reconstrucción de Jerusalén."],"modern":{"context":"Hogar","situation":"La casa necesita ordenarse y cada persona espera que empiece otra.","options":["Repartir tareas según las posibilidades de cada uno.","Discutir para ver quién tiene más culpa.","Hacer una lista sin asignar ninguna tarea."],"correct":0,"explanation":"La cooperación reconoce que las tareas y capacidades pueden ser diferentes. Pedir ayuda y agradecerla facilita que todos participen.","action":"Preparar un plan de tres tareas con responsables voluntarios.","talk":"¿Cómo repartimos el trabajo de manera justa, no solo idéntica?","responses":["Repartir tareas voluntarias según las posibilidades permite que todos contribuyan de manera justa.","Discutir sobre la culpa puede consumir el tiempo necesario para empezar. Una tarea concreta ayuda a avanzar.","Una lista sin responsables puede dejar el trabajo igual. Acordar quién hará qué vuelve útil el plan."],"line":"Piensa cómo expresarías tu respuesta con tus propias palabras."},"scene":"city","bridge":{"past":"Se termina la reconstrucción.","value":"Cooperación","today":"La casa necesita ordenarse y cada persona espera que empiece otra.","action":"Preparar un plan de tres tareas con responsables voluntarios."},"originalSourceArtwork":false},{"id":"maria","name":"María","title":"Dispuesta a aprender","era":"Jesús y sus enseñanzas","place":"Nazaret","value":"Humildad","reference":"Lucas 1:26–38","bible":"https://www.jw.org/es/biblioteca/biblia/biblia-estudio/libros/lucas/1/","source":"https://www.jw.org/es/biblioteca/libros/lecciones-historias-biblia/11/angel-gabriel-visita-maria/","summary":"María recibió del ángel Gabriel un mensaje inesperado: sería la madre de Jesús. Hizo una pregunta para comprender mejor lo que iba a suceder y expresó su disposición a servir a Jehová. Su respuesta combina humildad, interés por entender y voluntad de asumir una responsabilidad.","sequence":["Gabriel visita a María.","Le comunica el mensaje sobre Jesús.","María pregunta para comprender.","Expresa su disposición a servir a Jehová."],"clues":["Vivía en Nazaret.","Recibí una visita del ángel Gabriel.","Acepté la responsabilidad de ser la madre de Jesús."],"modern":{"context":"Aprendizaje","situation":"Te explican una responsabilidad, pero hay algo que no entiendes.","options":["Preguntar con respeto antes de comprometerte a hacerla.","Fingir que lo entendiste todo.","Suponer que preguntar demuestra incapacidad."],"correct":0,"explanation":"La humildad incluye reconocer que necesitamos información. Hacer una pregunta sincera puede evitar confusiones.","action":"Formular una pregunta que te ayude a entender una tarea.","talk":"¿Por qué a veces nos da vergüenza preguntar?","responses":["Una pregunta sincera aclara lo que se espera de ti antes de asumir la tarea.","Fingir que entendiste puede generar errores evitables y más preocupación después.","Preguntar no demuestra incapacidad. Puede mostrar interés por hacer bien una responsabilidad."],"line":"Piensa cómo expresarías tu respuesta con tus propias palabras."},"scene":"village","bridge":{"past":"Expresa su disposición a servir a Jehová.","value":"Humildad","today":"Te explican una responsabilidad, pero hay algo que no entiendes.","action":"Formular una pregunta que te ayude a entender una tarea."},"originalSourceArtwork":false},{"id":"samaritano","name":"El buen samaritano","title":"Detenerse sí importa","era":"Jesús y sus enseñanzas","place":"Camino a Jericó","value":"Compasión","reference":"Lucas 10:25–37","bible":"https://www.jw.org/es/biblioteca/biblia/biblia-estudio/libros/lucas/10/","source":"https://www.jw.org/es/biblioteca/libros/historias-biblicas/6/jesus-ensena/","summary":"Jesús contó una parábola sobre un viajero herido. Un sacerdote y un levita siguieron de largo; un samaritano se detuvo y organizó ayuda. La enseñanza dirige la atención a actuar con compasión, más allá de las diferencias entre las personas. Es una parábola, no la biografía de un personaje identificado.","sequence":["Un viajero es asaltado.","Dos personas pasan sin ayudarlo.","Un samaritano se detiene y lo atiende.","Lo lleva a un alojamiento y organiza su cuidado."],"clues":["Soy un personaje de una parábola de Jesús.","Me detuve cuando otros siguieron de largo.","Ayudé a un viajero herido en el camino a Jericó."],"modern":{"context":"Comunidad","situation":"Ves a una persona que necesita ayuda, pero no sabes si es seguro acercarte.","options":["Buscar ayuda adecuada y actuar sin exponerte a un peligro.","Grabarla para compartir el video.","Suponer que alguien más se hará cargo."],"correct":0,"explanation":"Ayudar incluye reconocer nuestros límites y pedir apoyo. Una acción útil y segura vale más que mirar o difundir la situación.","action":"Pensar a quién pedirías ayuda en una situación de necesidad.","talk":"¿Cómo mostramos compasión sin invadir la privacidad de alguien?","responses":["Buscar apoyo y actuar con prudencia permite ayudar sin añadir otra persona al peligro.","Grabar y difundir puede invadir la privacidad sin aportar la ayuda necesaria.","Suponer que otro actuará puede dejar la necesidad sin atender. Pedir ayuda adecuada ya es un paso útil."],"line":"Piensa cómo expresarías tu respuesta con tus propias palabras."},"scene":"desert","bridge":{"past":"Lo lleva a un alojamiento y organiza su cuidado.","value":"Compasión","today":"Ves a una persona que necesita ayuda, pero no sabes si es seguro acercarte.","action":"Pensar a quién pedirías ayuda en una situación de necesidad."},"originalSourceArtwork":false},{"id":"hijo","name":"El hijo que regresó","title":"Un nuevo comienzo","era":"Jesús y sus enseñanzas","place":"Lugar no especificado","value":"Arrepentimiento y perdón","reference":"Lucas 15:11–32","bible":"https://www.jw.org/es/biblioteca/biblia/biblia-estudio/libros/lucas/15/","source":"https://www.jw.org/es/biblioteca/libros/jesus/ministerio-al-este-jordan/parabola-hijo-perdido/","summary":"Jesús contó la parábola de un hijo que malgastó su herencia y decidió regresar arrepentido. Su padre lo recibió con alegría. El hermano mayor necesitó reflexionar sobre su propia reacción. La historia enseña sobre arrepentimiento y misericordia, y no especifica una ciudad donde hubiera sucedido.","sequence":["El hijo menor pide su herencia.","Se marcha y malgasta sus bienes.","Reconoce su error y decide volver.","Su padre lo recibe con alegría."],"clues":["Soy un personaje de una parábola, no una biografía.","Malgasté una herencia y decidí regresar arrepentido.","Mi padre me recibió con alegría aunque yo había tomado malas decisiones."],"modern":{"context":"Familia","situation":"Cometiste un error y te cuesta admitirlo porque temes la reacción.","options":["Reconocer lo ocurrido, disculparte y proponer una reparación.","Inventar una historia para ocultarlo.","Esperar que la persona lo olvide sin hablar."],"correct":0,"explanation":"Una disculpa sincera incluye responsabilidad y deseo de cambiar. La confianza puede necesitar tiempo y acciones consistentes.","action":"Practicar una disculpa sin añadir “pero tú también”.","talk":"¿Cómo podemos recibir una disculpa sin humillar a quien la ofrece?","responses":["Reconocer el daño y proponer una reparación da contenido a la disculpa. La respuesta de la otra persona puede necesitar tiempo.","Una historia para ocultarlo puede romper más la confianza y complicar la reparación.","El silencio no siempre resuelve el daño. Puedes preparar una disculpa breve y sincera."],"line":"Piensa cómo expresarías tu respuesta con tus propias palabras."},"scene":"village","bridge":{"past":"Su padre lo recibe con alegría.","value":"Arrepentimiento y perdón","today":"Cometiste un error y te cuesta admitirlo porque temes la reacción.","action":"Practicar una disculpa sin añadir “pero tú también”."},"originalSourceArtwork":false},{"id":"panes","name":"Jesús alimenta a la multitud","title":"Compartir y cuidar","era":"Jesús y sus enseñanzas","place":"Galilea","value":"Generosidad","reference":"Juan 6:1–13","bible":"https://www.jw.org/es/biblioteca/biblia/biblia-estudio/libros/juan/6/","source":"https://www.jw.org/es/biblioteca/libros/lecciones-historias-biblia/12/jesus-alimenta-miles/","summary":"Una gran multitud necesitaba alimento. Había cinco panes y dos pescados, una cantidad insuficiente para tanta gente. Jesús dio gracias y el relato describe cómo todos pudieron comer. Después se recogieron las sobras. El episodio permite reflexionar sobre compartir y no desperdiciar, sin presentar la generosidad como una fórmula para obtener milagros.","sequence":["La multitud necesita alimento.","Se identifican cinco panes y dos pescados.","Jesús da gracias y se distribuye la comida.","Se recogen las sobras."],"clues":["En este relato una multitud necesitaba comer.","Había cinco panes y dos pescados.","¿Quién realizó el milagro con el que todos comieron?"],"modern":{"context":"Hogar","situation":"Al terminar una comida familiar queda alimento en buen estado.","options":["Organizar cómo conservarlo o compartirlo de forma segura.","Desecharlo por no pensar qué hacer.","Servir más de lo que todos necesitan."],"correct":0,"explanation":"Cuidar los recursos y planificar las cantidades puede ser una manera práctica de mostrar agradecimiento.","action":"Organizar las porciones de la próxima comida para evitar desperdicios.","talk":"¿Qué recursos, además del alimento, podemos cuidar juntos?","responses":["Organizar las sobras en buen estado ayuda a cuidar los recursos y a evitar el desperdicio.","Desecharlas sin pensar puede desperdiciar alimento aprovechable. Planificar antes facilita una decisión segura.","Servir más de lo necesario puede generar nuevos desperdicios. Ajustar las porciones es una acción práctica."],"line":"Piensa cómo expresarías tu respuesta con tus propias palabras."},"scene":"coast","bridge":{"past":"Se recogen las sobras.","value":"Generosidad","today":"Al terminar una comida familiar queda alimento en buen estado.","action":"Organizar las porciones de la próxima comida para evitar desperdicios."},"originalSourceArtwork":false},{"id":"pedro","name":"Pedro","title":"Levantarse después de fallar","era":"Primeros discípulos","place":"Jerusalén","value":"Arrepentimiento","reference":"Lucas 22:54–62; Juan 21:15–17","bible":"https://www.jw.org/es/biblioteca/biblia/biblia-estudio/libros/lucas/22/","source":"https://www.jw.org/es/biblioteca/libros/lecciones-historias-biblia/13/pedro-niega-jesus-tres-veces/","summary":"Por miedo, Pedro negó conocer a Jesús. Después comprendió lo que había hecho y lloró. Su historia no terminó en ese error: Jesús volvió a confiarle responsabilidades. El relato ayuda a hablar del arrepentimiento, de aceptar ayuda y de no definir toda una vida por un fallo.","sequence":["Arrestan a Jesús.","Pedro niega conocerlo.","Reconoce su error y llora.","Más adelante Jesús le confía el cuidado de sus ovejas."],"clues":["Era pescador y llegué a ser apóstol.","Por miedo negué conocer a Jesús.","Después recibí el encargo de cuidar a sus ovejas."],"modern":{"context":"Escuela","situation":"Por presión dijiste algo que hirió a otra persona y ahora te pesa.","options":["Reconocerlo, disculparte y buscar cómo no repetirlo.","Decidir que ya no vale la pena mejorar.","Culpar únicamente al grupo."],"correct":0,"explanation":"Asumir la responsabilidad permite reparar y aprender. Sentirse mal no tiene por qué convertirse en pensar que no valemos nada.","action":"Identificar una decisión diferente para una próxima situación parecida.","talk":"¿Cómo podemos animar a alguien a corregir un error sin minimizar lo ocurrido?","responses":["Asumir lo que dijiste y preparar otra respuesta permite reparar y aprender sin definirte solo por el error.","Pensar que ya no puedes mejorar puede bloquear un cambio posible. Un error no resume toda tu vida.","La presión explica parte de lo ocurrido, pero no reemplaza tu responsabilidad de reparar el daño."],"line":"Piensa cómo expresarías tu respuesta con tus propias palabras."},"scene":"courtyard","bridge":{"past":"Más adelante Jesús le confía el cuidado de sus ovejas.","value":"Arrepentimiento","today":"Por presión dijiste algo que hirió a otra persona y ahora te pesa.","action":"Identificar una decisión diferente para una próxima situación parecida."},"originalSourceArtwork":false},{"id":"dorcas","name":"Dorcas","title":"Manos que cuidan","era":"Primeros discípulos","place":"Jope","value":"Bondad","reference":"Hechos 9:36–42","bible":"https://www.jw.org/es/biblioteca/biblia/biblia-estudio/libros/hechos/9/","source":"https://www.jw.org/es/biblioteca/libros/Perspicacia-para-comprender-las-Escrituras/Dorcas/","summary":"Dorcas, también llamada Tabita, era una discípula conocida por sus buenas obras y su ayuda a personas necesitadas. Después de su muerte, unas viudas mostraron a Pedro prendas que ella había hecho. El relato cuenta que Pedro oró y ella volvió a vivir. Sus acciones habían dejado una huella de cariño.","sequence":["Dorcas ayuda a personas necesitadas.","Enferma y muere.","Las viudas muestran a Pedro las prendas que hizo.","Pedro ora y Dorcas vuelve a vivir."],"clues":["También me llamaban Tabita.","Ayudaba con buenas obras y prendas de vestir.","Las viudas de Jope mostraron a Pedro lo que había hecho."],"modern":{"context":"Comunidad","situation":"Tienes una habilidad sencilla y no crees que pueda ayudar a nadie.","options":["Preguntar quién podría beneficiarse y ofrecer ayuda concreta.","Compararte hasta dejar de intentarlo.","Esperar a ser perfecto antes de colaborar."],"correct":0,"explanation":"Una habilidad cotidiana puede tener mucho valor para quien necesita ayuda. Lo importante no es impresionar.","action":"Ofrecer una habilidad: explicar, reparar, cocinar o acompañar.","talk":"¿Qué talentos de nuestra familia podríamos usar para cuidar a alguien?","responses":["Preguntar qué ayuda hace falta puede dar utilidad a una habilidad que para ti parece pequeña.","Compararte constantemente puede ocultar lo que ya sabes aportar. La ayuda no es una competición.","Esperar a ser perfecto puede posponer una ayuda sencilla que ya podrías ofrecer."],"line":"Piensa cómo expresarías tu respuesta con tus propias palabras."},"scene":"coast","bridge":{"past":"Pedro ora y Dorcas vuelve a vivir.","value":"Bondad","today":"Tienes una habilidad sencilla y no crees que pueda ayudar a nadie.","action":"Ofrecer una habilidad: explicar, reparar, cocinar o acompañar."},"originalSourceArtwork":false},{"id":"lidia","name":"Lidia","title":"Una puerta abierta","era":"Primeros discípulos","place":"Filipos","value":"Hospitalidad","reference":"Hechos 16:11–15, 40","bible":"https://www.jw.org/es/biblioteca/biblia/biblia-estudio/libros/hechos/16/","source":"https://www.jw.org/es/biblioteca/libros/Perspicacia-para-comprender-las-Escrituras/Lidia/","summary":"En Filipos, Pablo habló con unas mujeres reunidas junto a un río. Lidia, vendedora de púrpura, prestó atención al mensaje. Después de bautizarse con los de su casa, ofreció hospitalidad a Pablo y a sus compañeros. Su ejemplo conecta la atención al mensaje con la disposición a recibir y ayudar.","sequence":["Pablo y sus compañeros llegan a Filipos.","Hablan con mujeres reunidas junto a un río.","Lidia escucha y se bautiza con los de su casa.","Ofrece hospitalidad a los viajeros."],"clues":["Mi trabajo estaba relacionado con la púrpura.","Escuché a Pablo junto a un río.","Ofrecí mi casa a sus compañeros en Filipos."],"modern":{"context":"Comunidad","situation":"Llega una familia nueva a un grupo y todavía no conoce a nadie.","options":["Presentarte, escuchar y ofrecer una ayuda sin presionar.","Esperar que se adapte sin que nadie le hable.","Hacer preguntas personales que le incomoden."],"correct":0,"explanation":"La hospitalidad comienza con una bienvenida respetuosa. No requiere una casa grande ni gastar mucho.","action":"Preparar una bienvenida sencilla para alguien nuevo.","talk":"¿Qué gesto te hizo sentir bienvenido en un lugar desconocido?","responses":["Una bienvenida sin presión deja espacio para que la otra familia decida qué compartir y qué ayuda aceptar.","Esperar que se adapte sola puede prolongar la sensación de no conocer a nadie. Un saludo sencillo abre una puerta.","Preguntar detalles demasiado personales puede incomodar. La hospitalidad también respeta la privacidad."],"line":"Piensa cómo expresarías tu respuesta con tus propias palabras."},"scene":"river","bridge":{"past":"Ofrece hospitalidad a los viajeros.","value":"Hospitalidad","today":"Llega una familia nueva a un grupo y todavía no conoce a nadie.","action":"Preparar una bienvenida sencilla para alguien nuevo."},"originalSourceArtwork":false}]};